        dFast.x = clamp(dFast.x + aFast * (rawX - dFast.x), -3.2, 3.2);
        dFast.y = clamp(dFast.y + aFast * (rawY - dFast.y), -3.5, 3.5);
        dFast.z = clamp(dFast.z + aFast * (rawZ - dFast.z), -3.2, 3.2);

